"use client";

import Link from "next/link";
import { FormEvent, useState } from "react";
import { useParams } from "next/navigation";
import {
  ApiError,
  lodgeAppeal,
  type AppealOut,
} from "@/lib/api";
import {
  ApiErrorAlert,
  FieldMessage,
  fieldErrorMap,
} from "@/components/forms/ApiErrorAlert";
import { PageHeader } from "@/components/layout/PageHeader";
import { PageShell } from "@/components/layout/PageShell";
import { StatusBadge } from "@/components/layout/StatusBadge";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

export default function LodgeAppealPage() {
  const params = useParams<{ competitionId: string }>();
  const competitionId = params.competitionId;

  const [competitorId, setCompetitorId] = useState("");
  const [stageId, setStageId] = useState("");
  const [reason, setReason] = useState("");
  const [result, setResult] = useState<AppealOut | null>(null);
  const [error, setError] = useState<ApiError | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [pending, setPending] = useState(false);

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    setError(null);
    setFieldErrors({});
    setPending(true);
    try {
      const out = await lodgeAppeal(competitionId, {
        competitorId: competitorId.trim(),
        stageId: stageId.trim(),
        reason: reason.trim(),
      });
      setResult(out);
    } catch (err) {
      setResult(null);
      if (err instanceof ApiError) {
        setError(err);
        setFieldErrors(fieldErrorMap(err.fields));
      } else {
        setError(
          new ApiError(0, {
            error: {
              code: "HTTP_ERROR",
              message: "Could not lodge appeal",
              fields: [],
              traceId: "",
            },
          }),
        );
      }
    } finally {
      setPending(false);
    }
  }

  return (
    <PageShell width="narrow" className="space-y-6">
      <PageHeader
        title="Lodge an appeal"
        description="Submit within the configured appeal window. The case is acknowledged only when the server accepts it."
      />

      <ApiErrorAlert error={error} />

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Appeal details</CardTitle>
          <CardDescription>
            Competition <span className="font-mono text-xs">{competitionId}</span>
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={onSubmit} className="space-y-4" noValidate>
            <div className="space-y-2">
              <Label htmlFor="competitorId">Competitor ID</Label>
              <Input
                id="competitorId"
                className="min-h-11"
                value={competitorId}
                onChange={(e) => setCompetitorId(e.target.value)}
                required
                data-testid="appeal-competitor-id"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="stageId">Stage ID</Label>
              <Input
                id="stageId"
                className="min-h-11"
                value={stageId}
                onChange={(e) => setStageId(e.target.value)}
                required
                data-testid="appeal-stage-id"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="reason">Reason</Label>
              <Textarea
                id="reason"
                value={reason}
                onChange={(e) => setReason(e.target.value)}
                required
                rows={4}
                data-testid="appeal-reason"
              />
              <FieldMessage message={fieldErrors.reason} />
            </div>
            <Button
              type="submit"
              className="min-h-11 w-full"
              disabled={pending}
              data-testid="appeal-lodge"
            >
              {pending ? "Submitting…" : "Lodge appeal"}
            </Button>
          </form>
        </CardContent>
      </Card>

      {result ? (
        <Alert data-testid="appeal-lodged">
          <AlertTitle className="flex items-center gap-2">
            Appeal lodged <StatusBadge status={result.state} />
          </AlertTitle>
          <AlertDescription>
            Appeal ID{" "}
            <span className="font-mono text-xs" data-testid="appeal-id">
              {result.appealId}
            </span>
          </AlertDescription>
        </Alert>
      ) : null}

      <p className="text-xs text-muted-foreground">
        <Link href="/competitor" className="underline underline-offset-2">
          Back to competitor portal
        </Link>
      </p>
    </PageShell>
  );
}
